package com.nexloottracker;

import org.junit.Test;

import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class KillListFilterTest
{
	private static final ZoneId ZONE = ZoneId.of("Australia/Sydney");

	@Test
	public void filterByDateTodayIncludesKillsFromStartOfLocalDay()
	{
		final ZonedDateTime now = ZonedDateTime.of(2026, 7, 10, 11, 0, 0, 0, ZONE);
		final long todayStart = LocalDate.of(2026, 7, 10).atStartOfDay(ZONE).toInstant().toEpochMilli();
		final long yesterday = todayStart - 1;

		List<NexLootTracker> kills = new ArrayList<>();
		kills.add(killWithDate(yesterday));
		kills.add(killWithDate(todayStart));
		kills.add(killWithDate(todayStart + 60_000));

		ArrayList<NexLootTracker> filtered = KillListFilter.filterByDate(
			kills,
			"Today",
			now.toInstant().toEpochMilli(),
			ZONE
		);

		assertEquals(2, filtered.size());
	}

	@Test
	public void filterByDateTwelveHoursUsesRollingWindow()
	{
		final long now = 1_000_000_000_000L;
		final long since = KillListFilter.getSinceTimestamp("12 Hours", now, ZONE);

		List<NexLootTracker> kills = new ArrayList<>();
		kills.add(killWithDate(since - 1));
		kills.add(killWithDate(since));
		kills.add(killWithDate(now));

		ArrayList<NexLootTracker> filtered = KillListFilter.filterByDate(kills, "12 Hours", now, ZONE);

		assertEquals(2, filtered.size());
	}

	@Test
	public void filterByDateAllTimeReturnsEveryKill()
	{
		List<NexLootTracker> kills = new ArrayList<>();
		kills.add(killWithDate(1));
		kills.add(killWithDate(2));

		ArrayList<NexLootTracker> filtered = KillListFilter.filterByDate(kills, "All Time", 3, ZONE);

		assertEquals(2, filtered.size());
	}

	@Test
	public void getSinceTimestampTodayIsBeforeRollingTwentyFourHoursWhenMorning()
	{
		final ZonedDateTime morning = ZonedDateTime.of(2026, 7, 10, 11, 0, 0, 0, ZONE);
		final long now = morning.toInstant().toEpochMilli();
		final long todaySince = KillListFilter.getSinceTimestamp("Today", now, ZONE);
		final long rollingSince = now - 86_400_000L;

		assertTrue(todaySince > rollingSince);
	}

	private static NexLootTracker killWithDate(long date)
	{
		NexLootTracker kill = new NexLootTracker();
		kill.setDate(date);
		kill.setKillCountID("kill-" + date);
		return kill;
	}
}

package com.nexloottracker;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class NexPetMessageTest
{
	@Test
	public void recognizesFirstPetMessages()
	{
		assertTrue(NexLootTrackerPlugin.isFirstPetMessage(
			"You have a funny feeling like you're being followed."
		));
		assertTrue(NexLootTrackerPlugin.isFirstPetMessage(
			"You feel something weird sneaking into your backpack."
		));
	}

	@Test
	public void recognizesDuplicatePetMessage()
	{
		assertTrue(NexLootTrackerPlugin.isDuplicatePetMessage(
			"You have a funny feeling like you would have been followed..."
		));
	}

	@Test
	public void recognizesUntradeableNexlingMessage()
	{
		assertTrue(NexLootTrackerPlugin.isUntradeableNexlingMessage("Untradeable drop: Nexling"));
		assertTrue(NexLootTrackerPlugin.isUntradeableNexlingMessage("Untradeable drop: Nexling."));
	}

	@Test
	public void rejectsUnrelatedPetMessages()
	{
		assertFalse(NexLootTrackerPlugin.isUntradeableNexlingMessage("Untradeable drop: Pet chaos elemental"));
		assertFalse(NexLootTrackerPlugin.isFirstPetMessage("Your pet is not interested in that."));
		assertFalse(NexLootTrackerPlugin.isDuplicatePetMessage("You have a funny feeling like you're being followed."));
	}
}

package com.nexloottracker;

import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class NexKillContributionTrackerTest
{
	@Mock
	private Client client;

	@Mock
	private Player localPlayer;

	@Test
	public void getContributionPercentUsesLocalOverTotalDamage()
	{
		NexKillContributionTracker tracker = new NexKillContributionTracker();
		tracker.onHitsplatApplied(hitsplat(NpcID.NEX, 80, true, false), client);
		tracker.onHitsplatApplied(hitsplat(NpcID.NEX, 20, false, true), client);

		assertEquals(80.0, tracker.getContributionPercent(), 0.001);
	}

	@Test
	public void tracksNexMinionAndBloodReaverDamage()
	{
		NexKillContributionTracker tracker = new NexKillContributionTracker();
		List<Integer> contributionNpcIds = Arrays.asList(
			NpcID.NEX,
			NpcID.NEX_SPAWNING,
			NpcID.NEX_SOULSPLIT,
			NpcID.NEX_DEFLECT,
			NpcID.NEX_DYING,
			NpcID.NEX_SMOKEMAGE,
			NpcID.NEX_SHADOWMAGE,
			NpcID.NEX_BLOODMAGE,
			NpcID.NEX_ICEMAGE,
			NpcID.NEX_PRISON_BLOOD_REAVER,
			NpcID.NEX_PRISON_BLOOD_REAVER_BOSS
		);

		for (int npcId : contributionNpcIds)
		{
			tracker.onHitsplatApplied(hitsplat(npcId, 10, true, false), client);
		}

		assertEquals(contributionNpcIds.size() * 10, tracker.getLocalDamage());
		assertEquals(contributionNpcIds.size() * 10, tracker.getTotalDamage());
	}

	@Test
	public void ignoresNpcHitsOutsideNexEncounter()
	{
		NexKillContributionTracker tracker = new NexKillContributionTracker();
		tracker.onHitsplatApplied(hitsplat(NpcID.CORP_BEAST, 100, true, false), client);

		assertNull(tracker.getContributionPercent());
	}

	@Test
	public void ignoresHealingHitsplats()
	{
		NexKillContributionTracker tracker = new NexKillContributionTracker();
		tracker.onHitsplatApplied(hitsplat(NpcID.NEX, 40, true, false, HitsplatID.HEAL), client);

		assertNull(tracker.getContributionPercent());
	}

	@Test
	public void resetClearsTrackedDamage()
	{
		NexKillContributionTracker tracker = new NexKillContributionTracker();
		tracker.onHitsplatApplied(hitsplat(NpcID.NEX, 50, true, false), client);
		tracker.reset();

		assertNull(tracker.getContributionPercent());
	}

	private HitsplatApplied hitsplat(int npcId, int amount, boolean mine, boolean others)
	{
		return hitsplat(npcId, amount, mine, others, 0);
	}

	private HitsplatApplied hitsplat(int npcId, int amount, boolean mine, boolean others, int hitsplatType)
	{
		NPC npc = mock(NPC.class);
		when(npc.getId()).thenReturn(npcId);

		Hitsplat hitsplat = mock(Hitsplat.class);
		when(hitsplat.getAmount()).thenReturn(amount);
		when(hitsplat.getHitsplatType()).thenReturn(hitsplatType);
		when(hitsplat.isMine()).thenReturn(mine);
		when(hitsplat.isOthers()).thenReturn(others);

		HitsplatApplied event = mock(HitsplatApplied.class);
		when(event.getActor()).thenReturn(npc);
		when(event.getHitsplat()).thenReturn(hitsplat);
		when(client.getLocalPlayer()).thenReturn(localPlayer);

		return event;
	}
}

