	public BufferedImage resizeImage(BufferedImage image, double scale, int transformType)
	{
		if (image == null)
		{
			return null;
		}

		int width = (int) (image.getWidth() * scale);
		int height = (int) (image.getHeight() * scale);
		BufferedImage resized = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		AffineTransform transform = AffineTransform.getScaleInstance(scale, scale);
		AffineTransformOp op = new AffineTransformOp(transform, transformType);
		op.filter(image, resized);
		return resized;
	}

	private String getUniqueToolTip(NexUniques unique, int seen, int received)
	{
		String tip = "<html>" + unique.getName() + "<br>Received: " + received + "x<br>Seen: " + seen + "x";
		if (unique == NexUniques.NEXLING)
		{
			tip += "<br>Tertiary 1/500 (independent of unique table)";
		}
		return tip;
	}

	private String getRegularToolTip(NexLootTrackerItem drop)
	{
		return "<html>" + drop.getName() + " x " + drop.getQuantity() + "<br>Price: " + SplitChanger.format(drop.getPrice()) + " gp";
	}

	public void clearData()
	{
		int delete = JOptionPane.showConfirmDialog(
			getRootPane(),
			"<html>Are you sure you want to clear all Nex loot data?<br/>There is no way to undo this action.</html>",
			"Warning",
			JOptionPane.YES_NO_OPTION
		);

		if (delete == JOptionPane.YES_OPTION)
		{
			if (!fileReadWriter.delete())
			{
				JOptionPane.showMessageDialog(getRootPane(), "Unable to clear stored data, please try again.");
				return;
			}
			loadKillList();
		}
	}
}

package com.nexloottracker;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;

/**
 * Nex unique drop rates are rolled per kill (1/43 for any unique on the table).
 * A player's personal rate scales linearly with kill contribution, e.g. 20% contribution
 * yields a 1/215 chance for any unique (43 / 0.20 = 215).
 * Nexling is tertiary (1/500) and is tracked separately — it does not reset unique dry streaks.
 */
public final class DropRateCalculator
{
	public static final double ANY_UNIQUE_DENOMINATOR = 43.0;
	public static final double MVP_CONTRIBUTION_MULTIPLIER = 1.10;

	private DropRateCalculator()
	{
	}

	/**
	 * Effective drop contribution applies a 10% MVP boost when the local player was MVP.
	 * e.g. 20% damage share becomes 22% (20 × 1.10).
	 */
	public static Double getEffectiveKillContribution(NexLootTracker kill)
	{
		Double contribution = kill.getKillContribution();
		if (contribution == null)
		{
			return null;
		}

		double effective = contribution;
		if (kill.isMvpInOwnName())
		{
			effective *= MVP_CONTRIBUTION_MULTIPLIER;
		}

		return Math.max(0.0, Math.min(100.0, effective));
	}

	public static ArrayList<NexLootTracker> getDistinctKillsSortedByDate(List<NexLootTracker> kills)
	{
		LinkedHashMap<String, NexLootTracker> distinct = new LinkedHashMap<>();
		for (NexLootTracker kill : kills)
		{
			distinct.put(kill.getKillCountID(), kill);
		}

		ArrayList<NexLootTracker> sorted = new ArrayList<>(distinct.values());
		sorted.sort(Comparator.comparingLong(NexLootTracker::getDate));
		return sorted;
	}

	public static int getKillsSinceLastSeenUnique(List<NexLootTracker> kills)
	{
		ArrayList<NexLootTracker> distinct = getDistinctKillsSortedByDate(kills);
		distinct.sort(Comparator.comparingLong(NexLootTracker::getDate).reversed());

		int streak = 0;
		for (NexLootTracker kill : distinct)
		{
			if (hasSeenUnique(kill))
			{
				break;
			}
			streak++;
		}
		return streak;
	}

	/**
	 * Kills since the local player's last personal unique-table drop.
	 * Nexling is tertiary (1/500) and does not reset this streak.
	 * Computed from saved kill logs — same source of truth as the side panel.
	 */
	public static int getPersonalDryCount(List<NexLootTracker> kills)
	{
		return getKillsSinceLastOwnDrop(kills, DropRateCalculator::isAnyOwnUnique).size();
	}

	/**
	 * Most recent personal unique-table drop name from saved logs, or empty when none exist.
	 * Nexling is excluded (separate tertiary roll).
	 */
	public static String getLastOwnUniqueName(List<NexLootTracker> kills)
	{
		ArrayList<NexLootTracker> distinct = getDistinctKillsSortedByDate(kills);
		distinct.sort(Comparator.comparingLong(NexLootTracker::getDate).reversed());

		for (NexLootTracker kill : distinct)
		{
			if (isAnyOwnUnique(kill))
			{
				return kill.getSpecialLoot();
			}
		}

		return "";
	}

	public static DryStreakStats getDryStreakStats(List<NexLootTracker> kills)
	{
		return new DryStreakStats(
			getPersonalDryCount(kills),
			getKillsSinceLastSeenUnique(kills),
			getLastOwnUniqueName(kills)
		);
	}

	public static ArrayList<NexLootTracker> getKillsSinceLastOwnDrop(
		List<NexLootTracker> kills,
		Predicate<NexLootTracker> isOwnDrop
	)
	{
		ArrayList<NexLootTracker> distinct = getDistinctKillsSortedByDate(kills);

		int lastOwnDropIndex = -1;
		for (int i = 0; i < distinct.size(); i++)
		{
			if (isOwnDrop.test(distinct.get(i)))
			{
				lastOwnDropIndex = i;
			}
		}

		if (lastOwnDropIndex < 0)
		{
			return distinct;
		}

		if (lastOwnDropIndex == distinct.size() - 1)
		{
			return new ArrayList<>();
		}

		return new ArrayList<>(distinct.subList(lastOwnDropIndex + 1, distinct.size()));
	}

	public static Double getAverageKillContribution(List<NexLootTracker> kills)
	{
		double sum = 0.0;
		int count = 0;

		for (NexLootTracker kill : kills)
		{
			Double contribution = getEffectiveKillContribution(kill);
			if (contribution == null)
			{
				continue;
			}
			sum += contribution;
			count++;
		}

		if (count == 0)
		{
			return null;
		}

		return sum / count;
	}

	/**
	 * Average fight duration in milliseconds across kills that have {@code killDurationMs} set.
	 * Uses the same distinct-kill list callers already apply for Average Kill Contribution.
	 */
	public static Long getAverageKillDurationMs(List<NexLootTracker> kills)
	{
		long sum = 0L;
		int count = 0;

		for (NexLootTracker kill : kills)
		{
			Long durationMs = kill.getKillDurationMs();
			if (durationMs == null || durationMs < 0)
			{
				continue;
			}
			sum += durationMs;
			count++;
		}

		if (count == 0)
		{
			return null;
		}

		return Math.round((double) sum / count);
	}

	/**
	 * Formats a duration for display like the in-game chat timer ({@code 4:08}, or {@code 1:04:08}).
	 */
	public static String formatKillDuration(long durationMs)
	{
		long totalSeconds = Math.max(0L, Math.round(durationMs / 1000.0));
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;

		if (hours > 0)
		{
			return String.format(Locale.US, "%d:%02d:%02d", hours, minutes, seconds);
		}

		return String.format(Locale.US, "%d:%02d", minutes, seconds);
	}

	/**
	 * Returns how "due" a drop is relative to expected rate, walking kills in chronological order.
	 * Each kill with contribution adds {@code contribution% / dropRateDenominator} toward 1.0x.
	 * When the player receives a matching drop, 1.0 is subtracted so overdue progress carries over
	 * (e.g. 1.20x at drop becomes 0.20x). Early drops clamp at 0.00x.
	 */
	public static Double getDueMultiplier(
		List<NexLootTracker> kills,
		Predicate<NexLootTracker> isOwnDrop,
		double dropRateDenominator
	)
	{
		ArrayList<NexLootTracker> distinct = getDistinctKillsSortedByDate(kills);
		double due = 0.0;
		boolean hasContributionData = false;

		for (NexLootTracker kill : distinct)
		{
			Double contribution = getEffectiveKillContribution(kill);
			if (contribution != null && contribution > 0.0)
			{
				due += (contribution / 100.0) / dropRateDenominator;
				hasContributionData = true;
			}

			if (isOwnDrop.test(kill))
			{
				due = Math.max(0.0, due - 1.0);
			}
		}

		if (!hasContributionData)
		{
			return null;
		}

		return due;
	}

	public static String formatDueMultiplier(Double multiplier)
	{
		if (multiplier == null)
		{
			return "-";
		}

		return String.format(Locale.US, "%.2f", multiplier);
	}

	/**
	 * True when anyone on the team received a unique-table drop this kill.
	 * Nexling is tertiary and does not count.
	 */
	public static boolean hasSeenUnique(NexLootTracker kill)
	{
		return isUniqueTableDrop(kill.getSpecialLoot());
	}

	/**
	 * True when the local player received a unique-table drop this kill.
	 * Nexling is tertiary and does not count.
	 */
	public static boolean isAnyOwnUnique(NexLootTracker kill)
	{
		return kill.isSpecialLootInOwnName() && isUniqueTableDrop(kill.getSpecialLoot());
	}

	public static boolean isOwnUnique(NexLootTracker kill, NexUniques unique)
	{
		if (unique == NexUniques.NEXLING)
		{
			return kill.isPetInMyName();
		}

		return kill.isSpecialLootInOwnName()
			&& unique.getName().equalsIgnoreCase(kill.getSpecialLoot());
	}

	/**
	 * Unique drop table items only (excludes Nexling tertiary pet).
	 */
	public static boolean isUniqueTableDrop(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}

		final NexUniques unique = NexUniques.fromName(itemName);
		return unique != null && unique != NexUniques.NEXLING;
	}

	public static boolean isPetDrop(NexLootTracker kill)
	{
		return kill != null && !kill.getPetReceiver().isEmpty();
	}
}

package com.nexloottracker.filereadwriter;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.nexloottracker.NexLootTracker;
import com.nexloottracker.NexLootTrackerItem;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

@Slf4j
public class FileReadWriter
{
	private static final String DATA_FILE_NAME = "nex_loot_data.log";

	@Getter
	private String username;
	private String dataDir;

	@Inject
	@Setter
	private Gson gson;

	public void writeToFile(NexLootTracker kill)
	{
		if (dataDir == null || username == null || username.isEmpty())
		{
			log.error("Cannot write Nex kill: profile not initialized");
			return;
		}

		final String fileName = getDataFileName();

		try
		{
			log.info("Writing Nex kill to {}", fileName);
			FileWriter fw = new FileWriter(fileName, true);
			writeKillLine(fw, kill);
			fw.append("\n");
			fw.close();
		}
		catch (IOException ioe)
		{
			log.error("IOException in writeToFile: {}", ioe.getMessage());
		}
	}

	public String getJsonString(NexLootTracker kill, Gson gson, JsonParser parser)
	{
		JsonObject json = parser.parse(gson.toJson(kill)).getAsJsonObject();
		JsonArray lootListJson = new JsonArray();

		if (kill.getKillContribution() == null)
		{
			json.add("killContribution", JsonNull.INSTANCE);
		}
		else
		{
			json.addProperty("killContribution", kill.getKillContribution());
		}

		for (NexLootTrackerItem item : kill.getLootList())
		{
			lootListJson.add(parser.parse(gson.toJson(item, new TypeToken<NexLootTrackerItem>() {}.getType())));
		}

		json.addProperty("lootList", lootListJson.toString());
		return json.toString().replace("\\\"", "\"").replace("\"[", "[").replace("]\"", "]");
	}

	public ArrayList<NexLootTracker> readFromFile()
	{
		return readFromFile("");
	}

	public ArrayList<NexLootTracker> readFromFile(String alternateFile)
	{
		if (alternateFile.isEmpty() && (dataDir == null || username == null || username.isEmpty()))
		{
			log.warn("Cannot read Nex loot log before profile is set");
			return new ArrayList<>();
		}

		String fileName = alternateFile.isEmpty() ? getDataFileName() : alternateFile;
		boolean foundReplacementUnicode = false;

		try
		{
			log.info("Reading Nex loot log from {}", fileName);
			JsonParser parser = new JsonParser();
			BufferedReader reader = new BufferedReader(new FileReader(fileName));
			String line;
			ArrayList<NexLootTracker> killList = new ArrayList<>();

			while ((line = reader.readLine()) != null && !line.isEmpty())
			{
				if (line.contains("\uFFFD"))
				{
					foundReplacementUnicode = true;
					line = line.replace("\uFFFD", " ");
				}

				try
				{
					killList.add(gson.fromJson(parser.parse(line), NexLootTracker.class));
				}
				catch (JsonSyntaxException e)
				{
					log.warn("Bad line in Nex loot log: {}", line);
				}
			}

			reader.close();

			boolean needsRewrite = foundReplacementUnicode;
			for (NexLootTracker kill : killList)
			{
				boolean before = kill.isSpecialLootInOwnName();
				syncSpecialLootInOwnName(kill);
				if (before != kill.isSpecialLootInOwnName())
				{
					needsRewrite = true;
				}
			}

			if (needsRewrite)
			{
				log.info("Rewriting Nex loot log after syncing special loot ownership");
				updateKillList(killList);
			}

			log.info("Loaded {} Nex kills from {}", killList.size(), fileName);
			return killList;
		}
		catch (IOException e)
		{
			log.error("Error reading Nex loot log", e);
			return new ArrayList<>();
		}
	}

	public void createFolders()
	{
		File dir = new File(RUNELITE_DIR, "nex-loot-tracker");
		ignoreResult(dir.mkdir());
		dir = new File(dir, username);
		ignoreResult(dir.mkdir());
		dataDir = dir.getAbsolutePath();

		try
		{
			ignoreResult(new File(getDataFileName()).createNewFile());
		}
		catch (IOException e)
		{
			log.error("Error creating Nex loot data file", e);
		}
	}

	public void updateUsername(final String username)
	{
		this.username = username;
		createFolders();
	}

	public boolean ensureProfile(String preferredUsername, long accountHash)
	{
		if (preferredUsername != null && !preferredUsername.isEmpty())
		{
			updateUsername(preferredUsername);
			return true;
		}

		final String discovered = discoverProfile(accountHash);
		if (discovered != null)
		{
			log.info("Using discovered Nex loot profile: {}", discovered);
			updateUsername(discovered);
			return true;
		}

		if (accountHash != 0)
		{
			final String hashProfile = "account-" + accountHash;
			log.info("Creating Nex loot profile for account hash: {}", accountHash);
			updateUsername(hashProfile);
			return true;
		}

		log.warn("No Nex loot profile available yet");
		return false;
	}

	private String discoverProfile(long accountHash)
	{
		final File baseDir = new File(RUNELITE_DIR, "nex-loot-tracker");
		final File[] profileDirs = baseDir.listFiles(File::isDirectory);
		if (profileDirs == null || profileDirs.length == 0)
		{
			return null;
		}

		if (accountHash != 0)
		{
			for (File profileDir : profileDirs)
			{
				if (logContainsAccountHash(profileDir, accountHash))
				{
					return profileDir.getName();
				}
			}
		}

		String profileWithData = null;
		int profilesWithData = 0;

		for (File profileDir : profileDirs)
		{
			final File logFile = new File(profileDir, DATA_FILE_NAME);
			if (logFile.isFile() && logFile.length() > 0)
			{
				profilesWithData++;
				profileWithData = profileDir.getName();
			}
		}

		return profilesWithData == 1 ? profileWithData : discoverSoleProfileDirectory();
	}

	private String discoverSoleProfileDirectory()
	{
		final File baseDir = new File(RUNELITE_DIR, "nex-loot-tracker");
		final File[] profileDirs = baseDir.listFiles(File::isDirectory);
		if (profileDirs == null)
		{
			return null;
		}

		String soleProfile = null;
		for (File profileDir : profileDirs)
		{
			soleProfile = profileDir.getName();
		}

		return profileDirs.length == 1 ? soleProfile : null;
	}

	private boolean logContainsAccountHash(File profileDir, long accountHash)
	{
		final File logFile = new File(profileDir, DATA_FILE_NAME);
		if (!logFile.isFile())
		{
			return false;
		}

		try (BufferedReader reader = new BufferedReader(new FileReader(logFile)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty())
				{
					continue;
				}

				try
				{
					final NexLootTracker kill = gson.fromJson(new JsonParser().parse(line), NexLootTracker.class);
					if (kill.getAccountHash() == accountHash)
					{
						return true;
					}
				}
				catch (JsonSyntaxException ignored)
				{
				}
			}
		}
		catch (IOException e)
		{
			log.debug("Unable to scan Nex loot log in {}", profileDir.getName(), e);
		}

		return false;
	}

	public void updateKillList(ArrayList<NexLootTracker> killList)
	{
		try
		{
			String fileName = getDataFileName();
			FileWriter fw = new FileWriter(fileName, false);

			for (NexLootTracker kill : killList)
			{
				syncSpecialLootInOwnName(kill);

				writeKillLine(fw, kill);
				fw.append("\n");
			}

			fw.close();
		}
		catch (IOException e)
		{
			log.error("Error updating Nex loot log list", e);
		}
	}

	/**
	 * Infer whether a purple was received by the local player when persisting kills.
	 * Only ever upgrades {@code specialLootInOwnName} to {@code true}; never clears an
	 * existing own drop (e.g. after marking a received split as FFA).
	 */
	void syncSpecialLootInOwnName(NexLootTracker kill)
	{
		if (kill.getSpecialLoot().isEmpty())
		{
			return;
		}

		if (kill.getLootSplitPaid() > 0)
		{
			kill.setSpecialLootInOwnName(true);
			return;
		}

		if (kill.isFreeForAll()
			&& kill.getLootSplitReceived() > 0
			&& kill.getLootSplitReceived() == kill.getSpecialLootValue())
		{
			kill.setSpecialLootInOwnName(true);
			return;
		}

		if (!kill.getLootList().isEmpty()
			&& kill.getLootList().stream().anyMatch(item -> item.getName().equalsIgnoreCase(kill.getSpecialLoot())))
		{
			kill.setSpecialLootInOwnName(true);
		}
	}

	public void updateKill(NexLootTracker updatedKill)
	{
		try
		{
			String fileName = getDataFileName();
			ArrayList<NexLootTracker> killList = readFromFile();
			FileWriter fw = new FileWriter(fileName, false);

			for (NexLootTracker kill : killList)
			{
				if (kill.getUniqueID().equals(updatedKill.getUniqueID()))
				{
					kill = updatedKill;
				}

				writeKillLine(fw, kill);
				fw.append("\n");
			}

			fw.close();
		}
		catch (IOException e)
		{
			log.error("Error updating Nex kill entry", e);
		}
	}

	public boolean delete()
	{
		File file = new File(getDataFileName());
		boolean deleted = file.delete();

		try
		{
			ignoreResult(file.createNewFile());
		}
		catch (IOException e)
		{
			log.error("Error recreating Nex loot data file", e);
		}

		return deleted;
	}

	public String getDataFileName()
	{
		return dataDir + File.separator + DATA_FILE_NAME;
	}

	private void writeKillLine(FileWriter fw, NexLootTracker kill) throws IOException
	{
		JsonParser parser = new JsonParser();
		fw.write(getJsonString(kill, gson, parser));
	}

	private void ignoreResult(boolean ignored)
	{
	}
}

package com.nexloottracker;

import lombok.Value;

@Value
public class DryStreakStats
{
	int personalDry;
	int teamDry;
	String lastPersonalItem;
}

package com.nexloottracker;

import lombok.Data;

import java.util.ArrayList;
import java.util.UUID;

@Data
public class NexLootTracker
{
	long accountHash = -1;
	String profileType = "";
	boolean loggedIn = false;
	boolean killComplete = false;
	boolean freeForAll = false;

	int teamSize = -1;
	int completionCount = -1;

	String mvp = "";
	boolean mvpInOwnName = false;

	/**
	 * Kill contribution percent (0-100) derived from DPS Counter, if available.
	 * Null when DPS Counter is not enabled/installed or does not have data.
	 */
	Double killContribution = null;

	String specialLoot = "";
	String specialLootReceiver = "";
	boolean specialLootInOwnName = false;
	long specialLootValue = -1;

	String petReceiver = "";
	boolean petInMyName = false;

	long lootSplitReceived = -1;
	long lootSplitPaid = -1;

	ArrayList<NexLootTrackerItem> lootList = new ArrayList<>();

	String uniqueID = UUID.randomUUID().toString();
	String killCountID = UUID.randomUUID().toString();
	long date = System.currentTimeMillis();

	/**
	 * Fight duration in milliseconds, parsed from the chat "Fight duration: m:ss" message.
	 * Null when the duration message was not seen for this kill.
	 */
	Long killDurationMs = null;
}

package com.nexloottracker;

import net.runelite.api.Client;
import net.runelite.api.WorldType;

public final class WorldUtils
{
	private WorldUtils()
	{
	}

	public static boolean playerOnBetaWorld(Client client)
	{
		return client.getWorldType().contains(WorldType.BETA_WORLD);
	}
